const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const issue = payload.issue || {};
  const title = (issue.title || '').toLowerCase();
  const body = (issue.body || '').toLowerCase();
  const combined = title + ' ' + body;
  const repo = payload.repository || {};

  const labelRules = [
    { keywords: ['bug', 'error', 'crash', 'broken', 'fix', 'issue'], label: 'bug' },
    { keywords: ['feature', 'request', 'enhancement', 'add', 'new'], label: 'enhancement' },
    { keywords: ['docs', 'documentation', 'readme', 'typo', 'spelling'], label: 'documentation' },
    { keywords: ['performance', 'slow', 'optimize', 'speed', 'memory'], label: 'performance' },
    { keywords: ['security', 'vulnerability', 'cve', 'auth'], label: 'security' },
    { keywords: ['test', 'testing', 'coverage', 'ci', 'pipeline'], label: 'testing' },
    { keywords: ['ui', 'ux', 'design', 'css', 'layout', 'style'], label: 'ui/ux' }
  ];

  const assignRules = [
    { keywords: ['frontend', 'react', 'css', 'ui', 'ux'], assignee: 'frontend-dev' },
    { keywords: ['backend', 'api', 'database', 'server'], assignee: 'backend-dev' },
    { keywords: ['devops', 'ci', 'deploy', 'docker', 'infra'], assignee: 'devops-engineer' },
    { keywords: ['security', 'auth', 'vulnerability'], assignee: 'security-lead' }
  ];

  const labels = labelRules
    .filter(rule => rule.keywords.some(kw => combined.includes(kw)))
    .map(rule => rule.label);
  if (labels.length === 0) labels.push('triage');

  const assignee = assignRules.find(rule => rule.keywords.some(kw => combined.includes(kw)));

  return {
    json: {
      issueNumber: issue.number || 0,
      issueTitle: issue.title || '',
      repoOwner: repo.owner?.login || '',
      repoName: repo.name || '',
      repoFullName: repo.full_name || '',
      labels: labels,
      assignee: assignee?.assignee || '',
      action: payload.action || '',
      issueUrl: issue.html_url || '',
      author: issue.user?.login || ''
    }
  };
});
